/**
 * Project roots and mounts: find agents under a directory and load them into {@link AgentProject} manifests.
 */
import { access } from "node:fs/promises";
import { basename, join, resolve } from "node:path";
import { registerAuthoredModuleLoaders } from "../authored-loaders.js";
import { channelArchitectureError, channelArchitectureMigrationWarning, } from "../channel-architecture.js";
import { applyAgentContinuationDefaults, warnOmittedContinuationDowngrades, } from "../continuation-channel.js";
import { httpChannel } from "../http-channel-define.js";
import { otelProvidersReplaced } from "../otel/customer.js";
import { loadAgent, warnUnknownSlots } from "./agent.js";
import { loadChannels } from "./channels.js";
import { defaultImportModule, displayPath, pushConfigDiagnostic, } from "./context.js";
import { hasFlatLayoutMarkers, isDirectory, readPackageName, sortedEntries } from "./fs.js";
import { loadHooks } from "./hooks.js";
import { loadInstrumentation } from "./instrumentation.js";
import { NAME_PATTERN, RESERVED_SLUGS } from "./names.js";
import { loadReminders } from "./reminders.js";
import { loadSchedules } from "./schedules.js";
import { appendArtifactTool, loadArtifacts, loadStorage, mergeArtifacts, rejectLegacyOtelModule, rejectLegacyResult, } from "./services.js";
/**
 * True when `dir` looks like an agent project root: it has a nested `bot/`
 * directory, a compatible `agent/` directory, or flat-layout markers
 * (`agent.ts` / `instructions.md`) directly inside it.
 */
export async function isAgentProjectDir(dir) {
    const resolved = resolve(dir);
    if (!(await isDirectory(resolved))) {
        return false;
    }
    if ((await nestedProjectDir(resolved)) !== undefined) {
        return true;
    }
    return hasFlatLayoutMarkers(resolved);
}
async function nestedProjectDir(rootDir) {
    for (const name of ["bot", "agent"]) {
        const candidate = join(rootDir, name);
        if (await isDirectory(candidate)) {
            return candidate;
        }
    }
    return undefined;
}
/**
 * List agent projects directly under `rootDir` (one level deep) without
 * loading them. Empty when the path is missing or has no child agents.
 * Slug rules match {@link loadAgentProjects} / multi-agent serve.
 */
export async function listChildAgentDirs(rootDir) {
    const resolved = resolve(rootDir);
    if (!(await isDirectory(resolved))) {
        return [];
    }
    const results = [];
    const seenSlugs = new Set();
    for (const entry of await sortedEntries(resolved)) {
        if (!entry.isDirectory() || entry.name.startsWith(".")) {
            continue;
        }
        if (entry.name === "node_modules") {
            continue;
        }
        const childDir = join(resolved, entry.name);
        if (!(await isAgentProjectDir(childDir))) {
            continue;
        }
        if (await parentServeSkipped(childDir)) {
            continue;
        }
        const slug = assertSlug(entry.name, resolved);
        if (seenSlugs.has(slug)) {
            throw new Error(`Duplicate agent slug "${slug}" under ${resolved}.`);
        }
        seenSlugs.add(slug);
        results.push({ slug, dir: childDir });
    }
    return results;
}
/**
 * Discover the agent projects directly under `rootDir` (one level deep):
 * each immediate child directory that is itself an agent project becomes a
 * mounted agent, keyed by a slug derived from its directory name. Used for
 * multi-agent serving, where one server hosts many agents under
 * `/<slug>/...`. Throws when no child projects are found.
 */
export async function loadAgentProjects(rootDir, options = {}) {
    const resolved = resolve(rootDir);
    if (!(await isDirectory(resolved))) {
        throw new Error(`Agent projects directory does not exist: ${resolved}`);
    }
    const children = await listChildAgentDirs(resolved);
    if (children.length === 0) {
        throw new Error(`No agent projects found directly under ${resolved}. Each agent should be a subdirectory with its own bot/ directory (or flat-layout markers).`);
    }
    const results = [];
    // Storage namespaces (session mirror, host kv) key on the project
    // NAME, not the mount slug — two co-hosted agents sharing a name would
    // silently share sessions and KV state.
    const slugByName = new Map();
    for (const child of children) {
        const project = await loadAgentProject(child.dir, options);
        const priorSlug = slugByName.get(project.name);
        if (priorSlug !== undefined) {
            throw new Error(`Duplicate agent name "${project.name}" under ${resolved}: agents "${priorSlug}" and "${child.slug}" both resolve to it (package.json "name", or the directory name when unset). Co-hosted agents must have distinct names — their storage and session namespaces key on the name.`);
        }
        slugByName.set(project.name, child.slug);
        results.push({ slug: child.slug, project });
    }
    return results;
}
/**
 * Resolve mounts for `serve` / CLI. Defaults to multi-agent layout:
 * - `mode: "single"` — one agent at `/v1/*` (empty slug).
 * - otherwise, if `rootDir` is itself an agent project — one agent under
 *   `/<dirname>/...`.
 * - otherwise, every immediate child agent project under `/<slug>/...`.
 */
export async function resolveAgentMounts(rootDir, options = {}) {
    const { mode = "multi", ...discovery } = options;
    if (mode === "single") {
        return [{ slug: "", project: await loadAgentProject(rootDir, discovery) }];
    }
    if (await isAgentProjectDir(rootDir)) {
        const resolved = resolve(rootDir);
        const slug = assertSlug(basename(resolved), resolved);
        return [
            {
                slug,
                project: await loadAgentProject(rootDir, discovery),
            },
        ];
    }
    return loadAgentProjects(rootDir, discovery);
}
/** A child with this file stays out of a parent `serve` / `validate`. */
const PARENT_SERVE_SKIP_FILE = ".skip-parent-serve";
async function parentServeSkipped(dir) {
    try {
        await access(join(dir, PARENT_SERVE_SKIP_FILE));
        return true;
    }
    catch {
        return false;
    }
}
function assertSlug(name, parentDir) {
    if (!NAME_PATTERN.test(name) || RESERVED_SLUGS.has(name)) {
        throw new Error(`Cannot mount agent directory "${name}" under ${parentDir}: its name must match ${NAME_PATTERN} and not be one of ${[...RESERVED_SLUGS].join(", ")}.`);
    }
    return name;
}
export async function loadAgentProject(dir, options = {}) {
    // Public API: embedders can call discovery directly (without `serve()` or
    // the CLI), and it dynamically imports authored TypeScript.
    await registerAuthoredModuleLoaders();
    const rootDir = resolve(dir);
    if (!(await isDirectory(rootDir))) {
        throw new Error(`Agent project directory does not exist: ${rootDir}`);
    }
    const nestedAgentDir = await nestedProjectDir(rootDir);
    let agentDir;
    if (nestedAgentDir !== undefined) {
        agentDir = nestedAgentDir;
    }
    else if (await hasFlatLayoutMarkers(rootDir)) {
        agentDir = rootDir;
    }
    else {
        throw new Error(`No agent found under ${rootDir}: expected a bot/ directory (or a flat layout with agent.ts / instructions.md at the root)`);
    }
    const diagnostics = [];
    const ctx = {
        rootDir,
        diagnostics,
        importModule: options.importModule ?? defaultImportModule,
    };
    // Before agent.ts, tools, and channels. A meter created first stays a no-op.
    await loadInstrumentation(ctx, agentDir);
    const name = (await readPackageName(rootDir)) ?? basename(rootDir);
    const { agent, projectSlots } = await loadAgent(ctx, agentDir, {
        name,
        isRoot: true,
    });
    if (otelProvidersReplaced()) {
        ctx.diagnostics.push({
            severity: "warning",
            path: displayPath(ctx, join(agentDir, "agent.ts")),
            message: "A module replaced an OpenTelemetry provider BDK installed. The global API now uses that module's provider. See https://cursor.com/docs/bdk/guides/opentelemetry.",
        });
    }
    const { channels, httpChannelDefinition } = await loadChannels(ctx, join(agentDir, "channels"));
    for (const channel of projectSlots.channels) {
        if (channel.id === "http" || channels.some((c) => c.id === channel.id)) {
            pushConfigDiagnostic(ctx, {
                severity: "error",
                path: displayPath(ctx, join(agentDir, "extensions")),
                message: `Extension channel "${channel.id}" collides with an agent channel.`,
            });
            continue;
        }
        channels.push(channel);
    }
    const schedules = await loadSchedules(ctx, join(agentDir, "schedules"));
    schedules.push(...projectSlots.schedules);
    const reminders = await loadReminders(ctx, join(agentDir, "reminders"));
    reminders.push(...projectSlots.reminders);
    const hooks = await loadHooks(ctx, join(agentDir, "hooks"));
    hooks.push(...projectSlots.hooks);
    const storage = await loadStorage(ctx, agentDir, agent.architecture);
    const artifacts = await mergeProjectArtifacts(ctx, agentDir, projectSlots.artifacts);
    await rejectLegacyOtelModule(ctx, agentDir);
    await rejectLegacyResult(ctx, agentDir);
    await appendArtifactTool(ctx, agentDir, agent, artifacts);
    if (agentDir !== rootDir) {
        await warnUnknownSlots(ctx, agentDir);
    }
    const resolvedHttpChannel = httpChannelDefinition ?? httpChannel();
    for (const channel of channels) {
        const channelPath = displayPath(ctx, join(agentDir, "channels", `${channel.id}.ts`));
        const architectureError = channelArchitectureError(agent.architecture, channel.definition);
        if (architectureError !== undefined) {
            pushConfigDiagnostic(ctx, {
                severity: "error",
                path: channelPath,
                message: architectureError,
            });
        }
        const migrationWarning = channelArchitectureMigrationWarning(agent.architecture, channel.definition);
        if (migrationWarning !== undefined) {
            pushConfigDiagnostic(ctx, {
                severity: "warning",
                path: channelPath,
                message: migrationWarning,
            });
        }
    }
    warnOmittedContinuationDowngrades({
        architecture: agent.architecture,
        channels,
        warn: (id, message) => {
            pushConfigDiagnostic(ctx, {
                severity: "warning",
                path: displayPath(ctx, join(agentDir, "channels", `${id}.ts`)),
                message,
            });
        },
    });
    applyAgentContinuationDefaults({
        agent,
        channels,
        httpChannel: resolvedHttpChannel,
    });
    return {
        rootDir,
        agentDir,
        name: agent.name,
        agent,
        httpChannel: resolvedHttpChannel,
        channels,
        schedules,
        reminders,
        hooks,
        storage,
        artifacts,
        diagnostics,
    };
}
async function mergeProjectArtifacts(ctx, agentDir, extra) {
    const agent = await loadArtifacts(ctx, agentDir);
    if (extra === undefined) {
        return agent;
    }
    const kinds = { ...extra.kinds };
    const agentKinds = agent?.kinds;
    for (const kind of Object.keys(kinds)) {
        if (agentKinds !== undefined && kind in agentKinds) {
            ctx.diagnostics.push({
                severity: "error",
                path: displayPath(ctx, join(agentDir, "extensions")),
                message: `Extension artifact kind "${kind}" collides with an agent kind.`,
            });
            delete kinds[kind];
        }
    }
    return mergeArtifacts(agent, { ...extra, kinds });
}
/** True when the project has diagnostics that must block serving. */
export function hasErrorDiagnostics(project) {
    return project.diagnostics.some((d) => d.severity === "error");
}
export function formatDiagnostics(diagnostics) {
    return diagnostics
        .map((d) => {
        const location = d.path === undefined ? "" : ` (${d.path})`;
        return `${d.severity}: ${d.message}${location}`;
    })
        .join("\n");
}
export function formatValidateJson(mounts) {
    const agents = mounts.map(({ slug, project }) => ({
        slug,
        diagnostics: project.diagnostics.map((diagnostic) => ({
            severity: diagnostic.severity,
            code: diagnostic.code ?? "other",
            path: diagnostic.path,
            package: diagnostic.package,
            message: diagnostic.message,
        })),
    }));
    const ok = !agents.some((agent) => agent.diagnostics.some((diagnostic) => diagnostic.severity === "error"));
    return `${JSON.stringify({ version: 1, ok, agents })}\n`;
}
